#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, time, cost;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int V, N, M;
    cin >> V >> N >> M;

    vector<vector<Edge>> adj(N + 1);

    for (int i = 0; i < M; ++i) {
        int A, B, T, P;
        cin >> A >> B >> T >> P;
        adj[A].push_back({B, T, P});
        adj[B].push_back({A, T, P});
    }

    int X, Y;
    cin >> X >> Y;

    const long long INF = (1LL << 60);
    int W = N + 1;
    vector<long long> dist((V + 1) * W, INF);

    priority_queue<pair<long long, int>,
                   vector<pair<long long, int>>,
                   greater<pair<long long, int>>> pq;

    int start = 0 * W + X;
    dist[start] = 0;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, state] = pq.top();
        pq.pop();

        if (d != dist[state]) continue;

        int cost = state / W;
        int u = state % W;

        if (u == Y) {
            cout << d << '\n';
            return 0;
        }

        for (const Edge &e : adj[u]) {
            int nc = cost + e.cost;
            if (nc > V) continue;

            int ns = nc * W + e.to;
            long long nd = d + e.time;

            if (nd < dist[ns]) {
                dist[ns] = nd;
                pq.push({nd, ns});
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}
